test('prepared plan is bound to the earlier selected hash even if it changes before preparation', async () => {
  const f = await fixture()
  try {
    const selected = await api.selectReviewPolicy(f.release, f.owner, f.input)
    const run = path.join(f.temp, 'run')
    await fs.mkdir(run)
    const directory = await api.instance(f.release, f.owner, run, 'plan.md', selected)
    execFileSync('git', ['init', '-b', f.owner.branch], { cwd: f.owner.root, stdio: 'pipe' })
    execFileSync(
      'git',
      [
        '-c',
        'user.name=Fixture',
        '-c',
        'user.email=fixture@example.invalid',
        'commit',
        '--allow-empty',
        '-m',
        'fixture',
      ],
      { cwd: f.owner.root, stdio: 'pipe' },
    )
    const source = path.join(f.owner.root, 'plan.md')
    const original = await fs.readFile(source)
    await fs.appendFile(source, '\nChanged after selection, before source freeze\n')
    const request = {
      phase: 'PRE',
      scope: 'fixture approved stage',
      paths: ['plan.md'],
      prepared: path.join(run, 'prepared'),
    }
    const requestFile = path.join(run, 'request.json')
    await fs.writeFile(requestFile, JSON.stringify(request))
    const prepared = await api.execute(
      process.execPath,
      [path.join(directory, 'prepare-review.mjs'), requestFile],
      f.owner.root,
    )
    assert.equal(prepared.exit, 0, prepared.err)
    const packet = await fs.readFile(path.join(request.prepared, 'packet/plan.md'))
    assert.notDeepEqual(
      packet,
      original,
      'new candidate is internally consistent but its selection is stale',
    )
    assert.throws(() => api.verifyPlanSource(packet, selected.source), /PLAN_POLICY_DRIFT/)
    assert.equal(api.verifyPlanSource(original, selected.source), true)
  } finally {
    await fs.rm(f.temp, { recursive: true, force: true })
  }
})

test('POST-B01 supported config/model spellings cannot hide duplicate or conflicting overrides', () => {
  const selection = { stage: 'fixture', phase: 'POST', model: 'gpt-6-sol', reasoningEffort: 'high' }
  const args = ['--model', 'gpt-6-sol', '-c', 'model_reasoning_effort="high"']
  const record = (actual) => ({
    phase: 'POST',
    requestedModel: selection.model,
    requestedEffort: selection.reasoningEffort,
    cli: { args: actual },
  })
  for (const extra of [
    ['--config=model_reasoning_effort="xhigh"'],
    ['--config=model_reasoning_effort="high"'],
    ['--config', 'model_reasoning_effort="xhigh"'],
    ['-cmodel_reasoning_effort="xhigh"'],
    ['-c=model_reasoning_effort="xhigh"'],
    ['-c', '"model_reasoning_effort"="xhigh"'],
    ['-c', '"model_reasoning_effor\\u0074"="xhigh"'],
    ['-mgpt-6-astra'],
    ['-m=gpt-6-astra'],
    ['-c', 'model="gpt-6-astra"'],
  ])
    assert.throws(
      () => api.verifyRequestedPolicy(record([...args, ...extra]), selection),
      /INVOKED_POLICY_MISMATCH/,
    )
  for (const actual of [
    ['--model=gpt-6-sol', '--config=model_reasoning_effort="high"'],
    ['-m', 'gpt-6-sol', '--config', 'model_reasoning_effort="high"'],
    ['-mgpt-6-sol', '-cmodel_reasoning_effort="high"'],
    ['-m=gpt-6-sol', '-c=model_reasoning_effort="high"'],
  ])
    assert.equal(api.verifyRequestedPolicy(record(actual), selection), true)
})
import test from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
const fixturePolicy = {
  stage: 'existing-control-fixture',
  phase: 'PRE',
  model: 'gpt-6-astra',
  reasoningEffort: 'xhigh',
}
const baseline = process.env.FRADE_REVIEW_BASELINE === 'v3'
const legacy = await import('../../scripts/agent-review/transport/policy.mjs')
const api = baseline
  ? { strictReceipt: legacy.parseVerdict, discover: async () => ({ root: legacy.CANDIDATE }) }
  : await import('../../scripts/agent-review/core.mjs')
const stream = await fs.readFile(new URL('./fixtures/valid-cli.jsonl', import.meta.url), 'utf8')
const complete =
  JSON.stringify({ type: 'thread.started', thread_id: 'test-thread' }) +
  '\n' +
  JSON.stringify({ type: 'turn.started' }) +
  '\n' +
  JSON.stringify({ type: 'turn.completed' }) +
  '\n'
test('actual successful CLI stream and one-line PASS/FAIL are accepted', () => {
  assert.equal(api.strictReceipt(stream, 'GATE_STATUS: PASS\n', 0).gateStatus, 'PASS')
  assert.equal(api.strictReceipt(complete, 'GATE_STATUS: FAIL\n', 0).gateStatus, 'FAIL')
})
test('split-line verdict is rejected', () =>
  assert.throws(() => api.strictReceipt(complete, 'GATE_STATUS:\nPASS\n', 0)))
test('completed turn followed by incomplete turn is rejected', () =>
  assert.throws(() =>
    api.strictReceipt(
      complete + JSON.stringify({ type: 'turn.started' }) + '\n',
      'GATE_STATUS: PASS\n',
      0,
    ),
  ))
test('errors, duplicate verdict, nonzero, trailing item and missing thread fail closed', () => {
  for (const [s, r, c] of [
    [complete, 'GATE_STATUS: PASS\nGATE_STATUS: FAIL\n', 0],
    [complete, 'GATE_STATUS: PASS\n', 2],
    [complete + JSON.stringify({ type: 'error' }), 'GATE_STATUS: PASS\n', 0],
    [complete + JSON.stringify({ type: 'item.completed' }), 'GATE_STATUS: PASS\n', 0],
    [JSON.stringify({ type: 'turn.completed' }), 'GATE_STATUS: PASS\n', 0],
  ])
    assert.throws(() => api.strictReceipt(s, r, c))
})
test('registered worktree is discovered and unrelated repository with same origin rejected', async () => {
  const temp = await fs.mkdtemp(path.join(os.tmpdir(), 'frade-workflow-test-'))
  try {
    const primary = path.join(temp, 'primary'),
      other = path.join(temp, 'routing'),
      foreign = path.join(temp, 'foreign')
    await fs.mkdir(primary)
    await fs.mkdir(foreign)
    const git = (cwd, ...args) =>
      execFileSync('git', args, { cwd, encoding: 'utf8', stdio: 'pipe' })
    git(primary, 'init')
    git(
      primary,
      '-c',
      'user.name=Fixture',
      '-c',
      'user.email=fixture@example.invalid',
      'commit',
      '--allow-empty',
      '-m',
      'fixture',
    )
    git(primary, 'remote', 'add', 'origin', 'git@example.invalid:frade.git')
    git(primary, 'worktree', 'add', '-b', 'codex/routing', other)
    git(foreign, 'init')
    git(foreign, 'remote', 'add', 'origin', 'git@example.invalid:frade.git')
    const common = path.join(primary, '.git')
    assert.equal((await api.discover(other, common)).root, await fs.realpath(other))
    await assert.rejects(() => api.discover(foreign, common), /UNRELATED/)
  } finally {
    await fs.rm(temp, { recursive: true, force: true })
  }
})

